/**
 * Evaluates a declarative OutcomeSpec ("rules") so labs authored in the studio or generated by AI
 * run without custom code. Expressions go through a whitelist (arithmetic, comparisons, logic,
 * a few math functions) — student or teacher input is never executed as code.
 */
import { create, all, type MathNode } from "mathjs";
import type { OutcomeSpec } from "@/lib/domain";
import type { ExperimentOutcome } from "@/lib/engine/types";

const math = create(all, {});

const OPS = new Set(["add", "subtract", "multiply", "divide", "pow", "unaryMinus", "unaryPlus", "smaller", "larger", "smallerEq", "largerEq", "equal", "unequal", "and", "or", "not", "mod"]);
const FNS = new Set(["abs", "sqrt", "sin", "cos", "tan", "asin", "acos", "atan", "atan2", "exp", "log", "log10", "min", "max", "round", "floor", "ceil"]);
const CONSTS = new Set(["pi", "e", "true", "false"]);

export class RuleError extends Error {}

const cache = new Map<string, ReturnType<MathNode["compile"]>>();

export function compileRule(expr: string, vars: string[]) {
  const key = `${expr}|${vars.join(",")}`;
  const hit = cache.get(key);
  if (hit) return hit;
  if (expr.length > 400) throw new RuleError("expression too long");
  let node: MathNode;
  try {
    node = math.parse(expr);
  } catch (e) {
    throw new RuleError(`syntax: ${e instanceof Error ? e.message : e}`);
  }
  let count = 0;
  node.traverse((n, _p, parent) => {
    if (++count > 200) throw new RuleError("expression too complex");
    switch (n.type) {
      case "ConstantNode":
      case "ParenthesisNode":
        return;
      case "OperatorNode":
        if (!OPS.has((n as unknown as { fn: string }).fn)) throw new RuleError(`operator not allowed: ${(n as unknown as { op: string }).op}`);
        return;
      case "FunctionNode": {
        const name = (n as unknown as { fn: { name: string } }).fn.name;
        if (!FNS.has(name)) throw new RuleError(`function not allowed: ${name}`);
        return;
      }
      case "SymbolNode": {
        const name = (n as unknown as { name: string }).name;
        const isFn = parent?.type === "FunctionNode" && (parent as unknown as { fn: MathNode }).fn === n;
        if (isFn || CONSTS.has(name) || vars.includes(name)) return;
        throw new RuleError(`unknown symbol: ${name}`);
      }
      default:
        throw new RuleError(`not allowed: ${n.type}`);
    }
  });
  const compiled = node.compile();
  cache.set(key, compiled);
  return compiled;
}

/** Check every expression of a rules spec; returns problems (empty = valid). */
export function lintOutcome(spec: OutcomeSpec, vars: string[]): string[] {
  if (spec.kind === "engine") return [];
  const problems: string[] = [];
  const tryCompile = (expr: string, where: string) => {
    try {
      compileRule(expr, vars);
    } catch (e) {
      problems.push(`${where}: ${e instanceof Error ? e.message : e}`);
    }
  };
  spec.readouts.forEach((r, i) => tryCompile(r.expr, `readouts[${i}]`));
  tryCompile(spec.success, "success");
  spec.messages.forEach((m, i) => tryCompile(m.when, `messages[${i}].when`));
  return problems;
}

export function evaluateOutcomeRules(spec: Extract<OutcomeSpec, { kind: "rules" }>, params: Record<string, number>): ExperimentOutcome {
  const vars = Object.keys(params);
  const scope = { ...params };
  const num = (expr: string) => {
    const v = compileRule(expr, vars).evaluate({ ...scope });
    return typeof v === "number" ? v : Number(v);
  };
  const bool = (expr: string) => Boolean(compileRule(expr, vars).evaluate({ ...scope }));
  const readouts = spec.readouts.map((r) => {
    const v = num(r.expr);
    return { label: r.label, value: Number.isFinite(v) ? v.toFixed(r.digits) : "—", unit: r.unit };
  });
  const success = bool(spec.success);
  const message = spec.messages.find((m) => bool(m.when))?.text ?? (success ? "نجحت التجربة!" : "جرّب تاني.");
  return { success, message, readouts };
}
